  5	class MST {
  6	    private static final int NO_EDGE = 0;
  7	
  8	    static final class Edge {
  9	        final int from;
 10	        final int to;
 11	        final int weight;
 12	
 13	        Edge(int from, int to, int weight) {
 14	            this.from = from;
 15	            this.to = to;
 16	            this.weight = weight;
 17	        }
 18	    }
 19	
 20	    static final class Result {
 21	        final List<Edge> edges;
 22	        final int totalWeight;
 23	
 24	        Result(List<Edge> edges, int totalWeight) {
 25	            this.edges = edges;
 26	            this.totalWeight = totalWeight;
 27	        }
 28	    }
 29	
 30	    private int selectNextVertex(int[] key, boolean[] includedInMst) {
 31	        int minValue = Integer.MAX_VALUE;
 32	        int minIndex = -1;
 33	
 34	        for (int vertex = 0; vertex < includedInMst.length; vertex++) {
 35	            if (!includedInMst[vertex] && key[vertex] < minValue) {
 36	                minValue = key[vertex];
 37	                minIndex = vertex;
 38	            }
 39	        }
 40	
 41	        return minIndex;
 42	    }
 43	
 44	    private void validateGraph(int[][] graph) {
 45	        if (graph.length == 0) {
 46	            throw new IllegalArgumentException("Graph must contain at least one vertex.");
 47	        }
 48	
 49	        for (int[] row : graph) {
 50	            if (row.length != graph.length) {
 51	                throw new IllegalArgumentException("Graph must be a square adjacency matrix.");
 52	            }
 53	        }
 54	    }
 55	
 56	    private Result buildResult(int[] parent, int[][] graph) {
 57	        List<Edge> edges = new ArrayList<>();
 58	        int totalWeight = 0;
 59	
 60	        for (int vertex = 1; vertex < graph.length; vertex++) {
 61	            int from = parent[vertex];
 62	            int weight = graph[from][vertex];
 63	
 64	            edges.add(new Edge(from, vertex, weight));
 65	            totalWeight += weight;
 66	        }
 67	
 68	        return new Result(edges, totalWeight);
 69	    }
 70	
 71	    Result primMST(int[][] graph) {
 72	        validateGraph(graph);
 73	
 74	        int vertexCount = graph.length;
 75	        int[] parent = new int[vertexCount];
 76	        int[] key = new int[vertexCount];
 77	        boolean[] includedInMst = new boolean[vertexCount];
 78	
 79	        Arrays.fill(key, Integer.MAX_VALUE);
 80	        key[0] = 0;
 81	        parent[0] = -1;
 82	
 83	        for (int count = 0; count < vertexCount - 1; count++) {
 84	            int currentVertex = selectNextVertex(key, includedInMst);
 85	
 86	            if (currentVertex == -1) {
 87	                throw new IllegalStateException("Graph must be connected.");
 88	            }
 89	
 90	            includedInMst[currentVertex] = true;
 91	
 92	            for (int neighbor = 0; neighbor < vertexCount; neighbor++) {
 93	                int edgeWeight = graph[currentVertex][neighbor];
 94	
 95	                if (edgeWeight != NO_EDGE && !includedInMst[neighbor]
 96	                    && edgeWeight < key[neighbor]) {
 97	                    parent[neighbor] = currentVertex;
 98	                    key[neighbor] = edgeWeight;
 99	                }
100	            }
101	        }
102	
103	        return buildResult(parent, graph);
104	    }
105	
106	    void printMST(Result result) {
107	        System.out.println("Edge \tWeight");
108	        for (Edge edge : result.edges) {
109	            System.out.println(edge.from + " - " + edge.to + "\t" + edge.weight);
110	        }
111	    }
