113	    public static void main(String[] args)
114	    {
115	        MST t = new MST();
116	        int graph[][] = new int[][] { { 0, 2, 0, 6, 0 },
117	                                      { 2, 0, 3, 8, 5 },
118	                                      { 0, 3, 0, 0, 7 },
119	                                      { 6, 8, 0, 0, 9 },
120	                                      { 0, 5, 7, 9, 0 } };
121	
122	        Result result = t.primMST(graph);
123	        t.printMST(result);
124	    }
